import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Gamepad2, ArrowLeft, User, Mail, Lock } from "lucide-react";
import "./App.css";

export default function Signup() {
  const navigate = useNavigate();

  // 1. We need these "Variables" to hold what you type
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  // 2. This function sends your data to the Backend
  const handleSignup = async (e) => {
    e.preventDefault(); // Stops the page from refreshing

    try {
      const response = await fetch("http://localhost:4000/api/auth/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, email, password }), // Sending the data!
      });

      const data = await response.json();

      if (response.ok) {
        alert("Account Created Successfully! Now please Login.");
        navigate("/login");
      } else {
        alert(data.message || "Signup Failed");
      }
    } catch (error) {
      console.error("Error:", error);
      alert("Server error. Is your Backend running?");
    }
  };

  return (
    <div className="auth-container">
      {/* Left Side (Orange Theme) */}
      <div className="auth-left auth-left-orange-theme">
        <div className="auth-brand">
          <Gamepad2 size={32} /> VidyaQuest
        </div>
        <div className="auth-left-content">
          <h1 className="auth-title">Start Your <br/> Learning Journey!</h1>
          <p className="auth-desc">Join thousands of students learning STEM through fun games.</p>
        </div>
      </div>

      {/* Right Side (Form) */}
      <div className="auth-right">
        <div style={{ width: '100%', maxWidth: '400px', marginBottom: '1rem' }}>
           <div className="back-link" onClick={() => navigate("/")}>
             <ArrowLeft size={16} /> Back to Home
           </div>
        </div>

        <div className="auth-form-box">
          <h2>Create Account</h2>
          <p className="form-sub" style={{marginBottom:'1.5rem'}}>It's free and takes 1 minute</p>

          {/* 3. The Form MUST call handleSignup when submitted */}
          <form onSubmit={handleSignup}>

            <label>Full Name</label>
            <div className="input-group">
                <User size={18} className="input-icon" />
                <input 
                  type="text" 
                  placeholder="Rahul Kumar" 
                  className="input-field-icon" 
                  required 
                  value={name}
                  onChange={(e) => setName(e.target.value)} // Saves typing to variable
                />
            </div>

            <label style={{marginTop:'1rem'}}>Email</label>
            <div className="input-group">
                <Mail size={18} className="input-icon" />
                <input 
                  type="email" 
                  placeholder="rahul@school.com" 
                  className="input-field-icon" 
                  required 
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
            </div>

            <label style={{marginTop:'1rem'}}>Password</label>
            <div className="input-group">
                <Lock size={18} className="input-icon" />
                <input
                  type="password"
                  placeholder="Min 6 characters"
                  className="input-field-icon"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
            </div>

            <button type="submit" className="btn-auth orange-btn" style={{marginTop:'2rem'}}>
              Create Account
            </button>

          </form>

          <div className="auth-link" style={{marginTop: '1.5rem', textAlign: 'center'}}>
             Already have an account? <span style={{color: '#f97316', fontWeight: 'bold', cursor: 'pointer'}} onClick={() => navigate('/login')}>Sign In</span>
          </div>
        </div>
      </div>
    </div>
  );
}
